  },
  \"semantics\": {
    \"capture\": \"On each rising and falling edge of clk, q takes the d value sampled at that edge, with no extra cycle latency.\",
    \"hold\": \"q holds the last edge-sampled value between clock edges despite changes to d.\",
    \"reset\": \"No reset port or reset behavior is specified; none is added.\",
    \"initialization\": \"No power-up value is specified; registers are left uninitialized. Output before the first edge is unconstrained.\",
